sys_script_include.script:
/**
 * UpdateSetGitHubExporter
 * ------------------------------------------------------------------
 * Emulates the OOB "Export to XML" UI action (found on Update Sets /
 * Retrieved Update Sets) and commits the resulting XML file to a
 * GitHub repository.
 *
 * Target repo: https://github.com/JasonVonKrueger/instance-update-sets.git
 *
 * SETUP REQUIRED BEFORE USE
 * ------------------------------------------------------------------
 * 1. Create a GitHub Personal Access Token (classic or fine-grained)
 *    with "contents: read/write" permission on the target repo.
 *
 * 2. Create a Connection & Credential alias (System OAuth > Application
 *    Registry, or Connections & Credentials module) using Basic Auth:
 *       - Username: any non-empty string (e.g. "x-access-token")
 *       - Password: the GitHub PAT
 *    Note the alias name and set it below / via system property.
 *    NEVER hardcode the token directly in this script.
 *
 * 3. (Optional) Set system properties to avoid editing this file:
 *       x_github.owner  = JasonVonKrueger
 *       x_github.repo   = instance-update-sets
 *       x_github.branch = main
 *       x_github.credential_alias = <your alias name>
 *
 * USAGE
 * ------------------------------------------------------------------
 *   var exporter = new UpdateSetGitHubExporter();
 *   var result = exporter.commitUpdateSetToGitHub(currentUpdateSetSysId, {
 *       path: 'update-sets',              // optional subfolder in repo
 *       commitMessage: 'Custom message',  // optional
 *       branch: 'main'                    // optional override
 *   });
 *   // result = { success, path, branch, commitSha, fileUrl, recordCount, error }
 *
 * Typically wired up via:
 *   - A UI Action button on sys_update_set / sys_remote_update_set, or
 *   - A Business Rule (after update, when state changes to "complete")
 * ------------------------------------------------------------------
 */
var UpdateSetGitHubExporter = Class.create();
UpdateSetGitHubExporter.prototype = {
    initialize: function() {
        this.githubOwner = gs.getProperty('x_github.owner');
        this.githubRepo = gs.getProperty('x_github.repo');
        this.githubBranch = gs.getProperty('x_github.branch');
        this.githubApiBase = 'https://api.github.com';

        // Name of the Connection & Credential (Basic Auth) alias holding the GitHub PAT
        this.credentialAlias = gs.getProperty('x_github.credential_alias');
    },

    /**
     * Builds the same XML payload the "Export to XML" UI action produces.
     * @param {string} updateSetSysId - sys_id of sys_update_set (or sys_remote_update_set)
     * @returns {Object} { xml, name, sysId, recordCount }
     */
    exportUpdateSetToXML: function(updateSetSysId) {
        if (!updateSetSysId) {
            throw new Error('updateSetSysId is required');
        }

        var usGr = new GlideRecord('sys_update_set');
        var found = usGr.get(updateSetSysId);

        if (!found) {
            // Fall back to the retrieved/remote update set table
            usGr = new GlideRecord('sys_remote_update_set');
            found = usGr.get(updateSetSysId);
        }

        if (!found) {
            throw new Error('Update Set not found: ' + updateSetSysId);
        }

        var setName = usGr.getValue('name') || 'update_set';
        var sysId = usGr.getValue('sys_id');

        var xml = '<?xml version="1.0" encoding="UTF-8"?>\n';
        xml += '<unload unload_date="' + new GlideDateTime().getDisplayValue() + '">\n';

        var xmlGr = new GlideRecord('sys_update_xml');
        xmlGr.addQuery('update_set', sysId);
        xmlGr.orderBy('order');
        xmlGr.query();

        var count = 0;
        while (xmlGr.next()) {
            var payload = xmlGr.getValue('payload');
            if (payload) {
                xml += payload + '\n';
                count++;
            }
        }
        xml += '</unload>';

        gs.info('UpdateSetGitHubExporter: exported ' + count + ' customization record(s) for update set "' + setName + '" (' + sysId + ')');

        return {
            xml: xml,
            name: setName,
            sysId: sysId,
            recordCount: count
        };
    },

    /**
     * Exports the update set to XML and commits it to the configured GitHub repo.
     * @param {string} updateSetSysId
     * @param {Object} [options]
     * @param {string} [options.path] - subfolder within the repo, no leading/trailing slash
     * @param {string} [options.commitMessage] - custom commit message
     * @param {string} [options.branch] - override the default branch
     * @returns {Object} { success, path, branch, commitSha, fileUrl, recordCount, error }
     */
    commitUpdateSetToGitHub: function(updateSetSysId, options) {
        options = options || {};

        var exportResult;
        try {
            exportResult = this.exportUpdateSetToXML(updateSetSysId);
        } 
		catch (e) {
            gs.error('UpdateSetGitHubExporter: export failed - ' + e.message);
            return { success: false, error: e.message };
        }

        if (exportResult.recordCount === 0) {
            gs.warn('UpdateSetGitHubExporter: update set ' + exportResult.name + ' has no sys_update_xml records - committing an empty unload.');
        }

        var fileName = this._sanitizeFileName(exportResult.name) + '_' + exportResult.sysId.substring(0, 8) + '.xml';
        var repoPath = (options.path ? options.path.replace(/^\/|\/$/g, '') + '/' : '') + fileName;
        var branch = options.branch || this.githubBranch;
        var commitMessage = options.commitMessage ||
            ('Update Set export: ' + exportResult.name + ' (' + exportResult.sysId + ')');

        var existingSha = this._getExistingFileSha(repoPath, branch);
        var putResult = this._putFile(repoPath, exportResult.xml, commitMessage, branch, existingSha);

        return {
            success: putResult.success,
            path: repoPath,
            branch: branch,
            commitSha: putResult.commitSha,
            fileUrl: putResult.fileUrl,
            recordCount: exportResult.recordCount,
            error: putResult.error
        };
    },

    _sanitizeFileName: function(name) {
        return ('' + name).replace(/[^a-zA-Z0-9_\-]/g, '_');
    },

    /**
     * Checks whether the file already exists on the target branch and,
     * if so, returns its blob sha (required by GitHub to update a file).
     */
    _getExistingFileSha: function(repoPath, branch) {
        try {
            var r = new sn_ws.RESTMessageV2();
            r.setEndpoint(this.githubApiBase + '/repos/' + this.githubOwner + '/' + this.githubRepo +
                '/contents/' + repoPath + '?ref=' + encodeURIComponent(branch));
            r.setHttpMethod('GET');
            r.setAuthenticationProfile('basic', this.credentialAlias);
            r.setRequestHeader('Accept', 'application/vnd.github+json');
            r.setRequestHeader('X-GitHub-Api-Version', '2022-11-28');

            var response = r.execute();
            if (response.getStatusCode() == 200) {
                var body = JSON.parse(response.getBody());
                return body.sha;
            }
        } catch (e) {
            gs.warn('UpdateSetGitHubExporter: sha lookup failed (treating as new file) - ' + e.message);
        }
        return null;
    },

    /**
     * Creates or updates the file via GitHub's Contents API.
     * Note: the Contents API supports files up to ~1MB. For larger
     * update set exports, switch to the Git Data API (blob/tree/commit).
     */
    _putFile: function(repoPath, content, message, branch, sha) {
        try {
            var r = new sn_ws.RESTMessageV2();
            r.setEndpoint(this.githubApiBase + '/repos/' + this.githubOwner + '/' + this.githubRepo + '/contents/' + repoPath);
            r.setHttpMethod('PUT');
            r.setAuthenticationProfile('basic', this.credentialAlias);
            r.setRequestHeader('Accept', 'application/vnd.github+json');
            r.setRequestHeader('X-GitHub-Api-Version', '2022-11-28');
            r.setRequestHeader('Content-Type', 'application/json');

            var payload = {
                message: message,
                content: GlideStringUtil.base64Encode(content),
                branch: branch
            };
            if (sha) {
                payload.sha = sha;
            }
            r.setRequestBody(JSON.stringify(payload));

            var response = r.execute();
            var status = response.getStatusCode();
            var responseBody = response.getBody();

            if (status == 200 || status == 201) {
                var parsed = JSON.parse(responseBody);
                return {
                    success: true,
                    commitSha: parsed.commit ? parsed.commit.sha : null,
                    fileUrl: parsed.content ? parsed.content.html_url : null
                };
            }

            gs.error('UpdateSetGitHubExporter: GitHub commit failed [' + status + ']: ' + responseBody);
            return {
                success: false,
                error: 'HTTP ' + status + ': ' + responseBody
            };
        } 
		catch (e) {
            // Most commonly hit when this.credentialAlias doesn't match the
            // "ID" field of an existing Connection & Credential Alias record,
            // or the alias record isn't active / isn't type "Credential".
            var errMsg = 'REST call failed - check that credential alias "' + this.credentialAlias +
                '" exactly matches the ID field of an active Connection & Credential Alias (Basic Auth). ' +
                'Underlying error: ' + e.message;
            gs.error('UpdateSetGitHubExporter: ' + errMsg);
            return {
                success: false,
                error: errMsg
            };
        }
    },

    type: 'UpdateSetGitHubExporter'
};

var UpdateSetGitHubExporterAjax = Class.create();
UpdateSetGitHubExporterAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    exportUpdateSet: function() {
        var updateSetSysId = this.getParameter('sysparm_update_set_sys_id') || this.getParameter('sysparm_sys_id') || '';
        if (!updateSetSysId) {
            return this._jsonError('Missing required parameter: sysparm_update_set_sys_id');
        }

        try {
            var ExporterCtor = global.UpdateSetGitHubExporter || UpdateSetGitHubExporter;
            if (!ExporterCtor) {
                return this._jsonError('UpdateSetGitHubExporter is not available.');
            }

            var exporter = new ExporterCtor();
            var result = this._invokeExporter(exporter, updateSetSysId);
            return this._jsonOk(result);
        } 
		catch (ex) {
            return this._jsonError(ex && ex.message ? ex.message : String(ex));
        }
    },

    _invokeExporter: function(exporter, updateSetSysId) {
        var methodNames = ['exportUpdateSet', 'export', 'run', 'process'];
        for (var i = 0; i < methodNames.length; i++) {
            var methodName = methodNames[i];
            if (typeof exporter[methodName] === 'function') {
                return exporter[methodName](updateSetSysId);
            }
        }
        throw new Error('UpdateSetGitHubExporter does not expose a supported export method. Expected one of: ' + methodNames.join(', '));
    },

    _jsonOk: function(result) {
        return JSON.stringify({ ok: true, result: result });
    },

    _jsonError: function(message) {
        return JSON.stringify({ ok: false, error: message });
    },

    type: 'UpdateSetGitHubExporterAjax'
});

