sys_ui_action.script:
function deployToGit() {
    var updateSetSysId = g_form.getUniqueValue();
    var gm = new GlideModal('UpdateSetGitHubExporterModal');
    gm.setTitle('Deploy to Git');
    gm.setPreference('sysparm_update_set_sys_id', updateSetSysId);
    gm.render();

    return false;
}

function deploy() {	
	var ga = new GlideAjax('UpdateSetGitHubExporterAjax');
	var sysId = (typeof rowSysId == 'undefined') ? g_form.getUniqueValue() : rowSysId;

	ga.addParam('sysparm_update_set_sys_id', sysId);
	ga.addParam('sysparm_name', 'exportUpdateSet');
	ga.getXML(renderProgress);
}

function renderProgress(response) {
	ScriptLoader.getScripts('/scripts/ScanProgressViewerUtil.js', function() {
		var scanTitle = new GwtMessage().getMessage('Deploying to Git...');
		var hspvUtil = new ScanProgressViewerUtil();
		hspvUtil.renderProgress(response, scanTitle);
	});
}

sys_ui_page.client_script:
var USGE = {
    close: function() {
        var gm = GlideModal.get();
        if (gm) gm.destroy();
    },

    setStatus: function(msg, isError) {
        var el = document.getElementById('usge_status');
        if (!el) return;
        el.style.color = isError ? '#b10e1e' : '#0b5';
        el.textContent = msg;
    },

    deploy: function() {
        var gm = GlideModal.get();
        var updateSetSysId = gm ? gm.getPreference('sysparm_update_set_sys_id') : '';
        if (!updateSetSysId) {
            this.setStatus('Missing update set sys_id.', true);
            return;
        }

        this.setStatus('Deploy request in progress...', false);

        var ga = new GlideAjax('UpdateSetGitHubExporterAjax');
        ga.addParam('sysparm_name', 'exportUpdateSet');
        ga.addParam('sysparm_update_set_sys_id', updateSetSysId);
        ga.getXMLAnswer(function(answer) {
            var payload;
            try {
                payload = answer ? JSON.parse(answer) : {
                    ok: false,
                    error: 'Empty response from server.'
                };
            } 
			catch (e) {
                payload = {
                    ok: false,
                    error: 'Invalid JSON response from server: ' + String(answer)
                };
            }

            if (payload.ok) {
                USGE.setStatus('Deploy started successfully.', false);
            } 
			else {
                USGE.setStatus('Deploy failed: ' + (payload.error || 'Unknown error'), true);
            }
        });
    }
};
